const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(x,y,t,size=14,anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" text-anchor="${anchor}" fill="#466668">${esc(t)}</text>`;
const line=(x1,y1,x2,y2,color='#48696a',width=2)=>`<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}"/>`;
export function diagram(m,p,result=[],running=false){let body='',detail='Schematic · dimensions and colors are illustrative';const color=result.find(x=>x.label==='Appearance')?.value||'#93bdb7',phase=result.find(x=>x.label==='Phase')?.value;
 if(m.id==='vernier'){let raw=Math.round((p.size+p.zero)*10)/10,x=90+raw*8;for(let i=0;i<=80;i++)body+=line(90+i*8,110,90+i*8,i%5===0?150:135)+((i%5===0)?text(90+i*8,98,i,11):'');body+=`<rect x="70" y="151" width="690" height="25" rx="3" fill="#8aa6a5"/><path d="M90 176v85h25v-70M${x} 176v85h-25v-70" stroke="#3c6666" stroke-width="8" fill="none"/><rect x="${Math.min(90,x)}" y="220" width="${Math.max(2,x-90)}" height="25" fill="#c69a65"/><rect x="${x-8}" y="138" width="90" height="58" rx="4" fill="#e9f1df" stroke="#658d88"/>`;for(let j=0;j<=10;j++)body+=line(x+j*7.2,141,x+j*7.2,j%5===0?164:155,j===Math.round((raw-Math.floor(raw))*10)?'#c4774c':'#48696a')+(j%5===0?text(x+j*7.2,185,j,10):'');body+=text(430,300,'Main scale: mm · 10 vernier divisions span 9 mm · least count 0.1 mm');detail='Read the main scale just before vernier zero, then add the coinciding division × 0.1 mm.';
 }else if(m.id==='micrometer'){let raw=Math.round((p.size+p.zero)*100)/100,main=Math.floor(raw*2)/2,div=Math.round((raw-main)*100);body=`<path d="M210 100C80 60 80 280 210 250" stroke="#486a69" stroke-width="24" fill="none"/><rect x="190" y="165" width="90" height="20" fill="#c7a06b"/><rect x="280" y="130" width="220" height="85" rx="4" fill="#b8c9c3"/><rect x="500" y="110" width="120" height="125" rx="7" fill="#7c9e9b"/><rect x="620" y="140" width="75" height="65" rx="5" fill="#476b6b"/>`+line(290,174,620,174,'#e9eddd',2);for(let j=0;j<=10;j++)body+=line(300+j*17,174,300+j*17,j%2?190:150)+(j%2===0?text(300+j*17,142,(Math.max(0,main-2.5)+j*.5).toFixed(1),10):'');for(let j=-3;j<=3;j++)body+=line(500,174+j*14,530,174+j*14)+text(555,179+j*14,((div-j+50)%50),12);body+=text(425,285,`Sleeve reference ${main.toFixed(2)} mm · thimble divisions = 0.01 mm`);detail='Magnified schematic readout. Pitch 0.5 mm per revolution; 50 thimble divisions.';
 }else if(m.id==='spherometer'){body=`<path d="M150 270Q400 170 650 270" fill="#c2d9d4" stroke="#6f9690" stroke-width="3"/><path d="M250 232v-90h300v90M400 220V85" stroke="#4a7170" stroke-width="7"/><ellipse cx="400" cy="120" rx="100" ry="25" fill="#86a8a2"/><rect x="370" y="65" width="60" height="35" rx="7" fill="#4b7270"/>`+text(400,312,`Tripod spacing ${p.leg} mm · screw sagitta ${(p.sag+p.zero).toFixed(2)} mm`);
 }else if(m.id==='microscope'||m.id==='glass-depth'){body=`<path d="M180 280h400M240 280V60h260" stroke="#527978" stroke-width="12"/><path d="M470 80v90" stroke="#88aba5" stroke-width="40"/><path d="M455 170h30l-5 25h-20z" fill="#476c6c"/><rect x="390" y="235" width="160" height="40" fill="#c1d8d4" stroke="#6d9690"/><circle cx="650" cy="160" r="60" fill="#f5f8ed" stroke="#678e88"/><circle cx="650" cy="160" r="28" fill="none" stroke="#8ca9a1"/>`+line(590,160,710,160)+line(650,100,650,220)+text(400,316,'Move between two positions and subtract readings.');
 }else if(m.id==='meter-bridge'){let x=130+p.contact*5.4;body=`<path d="M130 220V100h200m140 0h200v120" stroke="#58857c" stroke-width="3" fill="none"/><rect x="240" y="82" width="70" height="35" fill="#cfa769"/><rect x="490" y="82" width="70" height="35" fill="#9bb9c5"/><circle cx="400" cy="145" r="25" fill="#eef4e8" stroke="#567d76"/><path d="M400 100v20M400 170L${x} 217" fill="none" stroke="#567d76" stroke-width="2"/><path d="M130 220H670" stroke="#b68b50" stroke-width="5"/>`+text(400,151,'G',17);for(let i=0;i<=100;i+=10)body+=line(130+i*5.4,222,130+i*5.4,235)+text(130+i*5.4,254,i,11);body+=text(x,286,`Jockey: ${p.contact.toFixed(1)} cm`);detail='Move the contact until the null detector offset is zero.';
 }else if(m.family==='scope'){let paths=[[],[]];for(let i=0;i<=240;i++){let pp={...p,time:.06*i/240},v=m.calculate(pp);paths[0].push(`${100+i*2.5},${180-v[0].value*6}`);paths[1].push(`${100+i*2.5},${180-v[1].value*6}`);}body=`<rect x="70" y="45" width="660" height="240" rx="12" fill="#203d3e"/>`;for(let i=0;i<7;i++)body+=line(100+i*100,70,100+i*100,260,'#486061',1);for(let i=0;i<5;i++)body+=line(100,80+i*40,700,80+i*40,'#486061',1);body+=`<polyline points="${paths[0].join(' ')}" fill="none" stroke="#d3a46a" stroke-width="2"/><polyline points="${paths[1].join(' ')}" fill="none" stroke="#91d0bb" stroke-width="3"/>`+text(400,315,'Gold: input · Mint: output · time window 60 ms');
 }else if(m.family==='logic'){let output=result[0]?.value||0;body=`<path d="M200 120h140M200 220h140M340 80h100Q580 170 440 260H340zM500 170h150" stroke="#577c76" stroke-width="4" fill="#d9e7da"/><circle cx="650" cy="170" r="30" fill="${output?'#c3d889':'#b8c4bc'}"/>`+text(190,125,p.a?'1':'0',22)+text(190,225,p.b?'1':'0',22)+text(420,176,p.gate,21)+text(650,177,output,22)+text(400,310,'Toggle inputs and record the truth table.');
 }else if(m.family==='pendulum'){let len=90+p.length*55;body=`<path d="M160 290V60h480v230" fill="none" stroke="#4d7373" stroke-width="10"/><path d="M400 60L445 ${60+len}" stroke="#738d84" stroke-width="2"/><circle cx="445" cy="${60+len}" r="22" fill="#c99b62" class="${running?'pulse':''}"/>`+text(400,322,`Measure ${p.cycles} oscillations at L = ${p.length} m`);
 }else if(m.family==='spring'){let load=p.mass||1,extension=Math.min(110,load*30);body=`<path d="M220 290V60h260" fill="none" stroke="#567a75" stroke-width="9"/><path d="M440 65v15`;for(let i=0;i<12;i++)body+=`l${i%2?-20:20} ${6+extension/12}`;body+=`v15" fill="none" stroke="#78928b" stroke-width="3"/><rect x="410" y="${185+extension}" width="60" height="35" rx="4" fill="#c59b65"/>`+text(400,325,'Measure load and extension; plot the linear elastic relationship.');
 }else if(m.family==='forces'){body=`<path d="M140 185h520" stroke="#79968d" stroke-width="12"/><path d="M400 185l-30 90h60z" fill="#527a72"/><path d="M220 185v65m360-65v65" stroke="#719087" stroke-width="2"/><rect x="195" y="245" width="50" height="35" fill="#ceaa72"/><rect x="555" y="245" width="50" height="35" fill="#83a9b0"/>`+text(400,85,m.id==='forces'?'Resolve forces and balance with an equilibrant':'Balance clockwise and anticlockwise moments',18);
 }else if(m.family==='fluid'||m.family==='tube'){let h=Math.max(70,Math.min(160,(p.water||p.head||p.temp||20)*3));body=`<path d="M260 70v170Q260 300 400 300T540 240V70" fill="none" stroke="#8fb0aa" stroke-width="28"/><path d="M260 ${h}v100Q260 285 400 285T540 225V140" fill="none" stroke="#acd3cb" stroke-width="18"/>`+line(180,70,180,280);for(let y=80;y<=280;y+=20)body+=line(180,y,195,y);body+=text(400,330,m.equation,15);
 }else if(m.family==='optics'){body=`<path d="M100 210h600" stroke="#93aba0" stroke-width="2"/><ellipse cx="400" cy="185" rx="18" ry="105" fill="#acd2d3" fill-opacity=".6" stroke="#709b9b"/><path d="M180 210V110m0 0-12 18m12-18 12 18M180 110h220l200 150M180 110l420 150" fill="none" stroke="#c49a60" stroke-width="2"/><path d="M600 210v50" stroke="#769faf" stroke-width="7"/>`+text(400,325,'Angle and image-position model · optical alignment is idealized');
 }else if(m.family==='wave'){let d='';for(let i=0;i<=120;i++)d+=(i?'L':'M')+(100+i*5)+' '+(180+55*Math.sin(i/120*Math.PI*4));body=`<path d="${d}" fill="none" stroke="#58958a" stroke-width="4"/><path d="M100 100v160M700 100v160" stroke="#4c7470" stroke-width="8"/>`+text(400,305,'Ideal standing-wave relationship: length, tension and frequency');
 }else if(m.family==='circuit'){body=`<path d="M170 130V75h460v180H170v-65" fill="none" stroke="#5e8b80" stroke-width="4"/><path d="M140 145h60M150 180h40" stroke="#567976" stroke-width="7"/><rect x="380" y="55" width="100" height="40" fill="#cba66e"/><circle cx="630" cy="165" r="35" fill="#eff3e7" stroke="#5b7e78" stroke-width="3"/>`+text(630,172,'A',23)+text(430,82,'R',18)+text(175,115,'+',20)+text(400,318,'Ideal circuit readouts · wiring and instrument range errors are excluded');
 }else if(m.family==='thermal'){let y=130;body=`<path d="M255 130v130q0 35 145 35t145-35V130" fill="#c0d8cd" stroke="#6d9388" stroke-width="3"/><ellipse cx="400" cy="130" rx="145" ry="28" fill="#e2ece0" stroke="#72988b"/><path d="M430 60v175" stroke="#82a39b" stroke-width="15"/><path d="M430 90v145" stroke="#c48962" stroke-width="5"/><circle cx="430" cy="240" r="10" fill="#c48962"/><path d="M300 140v80" stroke="#cfad75" stroke-width="28"/>`+text(400,330,'Calorimetric / thermal relationship · idealized heat balance');
 }else if(m.family==='titration'){let volume=p.titre||p.added||20,fill=100-Math.min(85,volume*2);body=`<path d="M230 300V50h170" fill="none" stroke="#567b72" stroke-width="8"/><rect x="385" y="55" width="30" height="150" rx="4" fill="#e3ece0" stroke="#72988a"/><rect x="389" y="${55+100-fill}" width="22" height="${50+fill}" fill="#a7ccc1"/><path d="M400 205v20m-16-9h32" stroke="#719b87" stroke-width="4"/><path d="M375 235v20l-50 65h150l-50-65v-20z" fill="#d7bfd0" fill-opacity=".8" stroke="#70958a"/>`;for(let i=0;i<12;i++)body+=line(386,65+i*10,395,65+i*10);body+=text(610,165,'Burette',17)+text(610,195,'Record initial and final readings',12);
 }else if(phase==='molecule'){let atoms=p.molecule==='CO2'?2:p.molecule==='BF3'||p.molecule==='NH3'?3:p.molecule==='H2O'?2:p.molecule==='SF6'?6:4;for(let i=0;i<atoms;i++){let a=2*Math.PI*i/atoms,x=400+105*Math.cos(a),y=180+85*Math.sin(a);body+=line(400,180,x,y,'#8ca99e',8)+`<circle cx="${x}" cy="${y}" r="24" fill="#d8c39a" stroke="#ad9468"/>`;}body+=`<circle cx="400" cy="180" r="34" fill="#8bafbb"/>`+text(400,305,result[0]?.value||'Select a molecule',18);detail='Schematic projection, not a bond-angle-accurate 3D molecular model.';
 }else if(phase==='flame'){body=`<path d="M400 60C470 155 495 175 475 230Q400 300 325 230C305 175 365 150 400 60" fill="${color}" opacity=".85" class="${running?'pulse':''}"/><path d="M400 150Q440 240 400 255Q360 240 400 150" fill="#fff1be"/><rect x="375" y="260" width="50" height="55" fill="#4d7470"/>`;
 }else if(phase==='beam'){body=`<rect x="130" y="115" width="540" height="120" rx="50" fill="#cadbd2" stroke="#759b8e"/><path d="M180 175Q400 ${p.field===1?80:p.field===2?270:175} 620 175" fill="none" stroke="#7cc28f" stroke-width="6"/><rect x="605" y="140" width="12" height="70" fill="#d1e6bb"/>`;
 }else if(phase==='spots'){body=`<rect x="270" y="65" width="260" height="235" fill="#f1edd9" stroke="#8ba797"/>`+line(285,270,515,270)+line(285,95,515,95);for(let i=0;i<3;i++)body+=`<ellipse cx="400" cy="${250-i*(p.stage||0)*40}" rx="18" ry="8" fill="${['#c7a967','#a3b978','#a090ba'][i]}"/>`;
 }else{body=`<path d="M290 70v180q0 50 110 50t110-50V70" fill="#f0f5e9" fill-opacity=".5" stroke="#7b9f90" stroke-width="3"/><path d="M295 160v90q0 45 105 45t105-45v-90z" fill="${color}" opacity=".7"/>`;if(phase==='layers')body+=`<path d="M295 160h210v55H295z" fill="#d5b46c" opacity=".8"/>`;if(phase==='precipitate')for(let i=0;i<35;i++)body+=`<circle cx="${310+(i*47)%180}" cy="${250+(i*13)%37}" r="4" fill="${color}" stroke="#9cae96"/>`;if(phase==='gas'||phase==='foam')for(let i=0;i<10;i++)body+=`<circle class="${running?'bubble':''}" cx="${330+(i*37)%140}" cy="${120+(i*19)%130}" r="${3+i%4}" fill="none" stroke="#87a995"/>`;body+=text(400,330,m.kind==='demonstration'?'Virtual observation · isolated samples':'Choose conditions, take a reading, then record it',14);}
 return `<svg viewBox="0 0 820 370" role="img" aria-label="${esc(m.title)} interactive schematic"><defs><pattern id="papergrid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#dce6d7" stroke-width=".6"/></pattern></defs><rect width="820" height="370" fill="url(#papergrid)"/>${body}</svg><p class="diagram-caption">${esc(detail)}</p>`;
}
