// Original idealized analytical models. These are not equipment-performance specifications.
export const models={};
export const N=(id,label,min,max,step,value,unit='')=>({id,label,min,max,step,value,unit});
export const S=(id,label,options,value=options[0][0])=>({id,label,options,value});
const out=(label,value,unit='')=>({label,value,unit});
function add(id,title,family,controls,equation,calculate,notes,apparatus,steps){models[id]={id,title,family,controls,equation,calculate,notes,apparatus:apparatus||[title+' apparatus','Measuring scale','Observation record'],kind:'analytical',steps:steps||['Set the independent variable and keep the other quantities fixed.','Take a virtual reading and add it to the observation table.','Repeat with at least three settings; select graph axes to examine the relationship.','Calculate the required quantity, state units, and discuss the model assumptions.']};}
const G=9.81,R=8.314462618,F=96485.332;
const rad=x=>x*Math.PI/180;
const sat=t=>.61078*Math.exp(17.27*t/(t+237.3));
const mass=N('mass','Mass',.05,1,.01,.2,'kg');
const voltage=N('voltage','Voltage',0,12,.1,3,'V');
const length=N('length','Length',.2,2,.05,1,'m');
const temp=N('temp','Temperature',10,90,1,30,'°C');
for(const [id,title,lc,max]of[['vernier','Vernier calipers',.1,80],['micrometer','Micrometer screw gauge',.01,25]])add(id,title,'instrument',[N('size','Specimen dimension',.1,max,lc,12.3,'mm'),N('zero','Zero error',-.1,.1,lc,0,'mm')], 'corrected reading = indicated reading − zero error',p=>{const indicated=Math.round((p.size+p.zero)/lc)*lc;return [out('Indicated reading',indicated,'mm'),out('Corrected reading',indicated-p.zero,'mm'),out('Least count',lc,'mm')];},'Ideal scale-reading practice with a fixed least count. Specimen size is the simulator setting. Jaw pressure, contact error, and ratchet technique are not simulated.',[title,'Virtual specimen','Zero reference']);
add('spherometer','Spherometer: radius of curvature','instrument',[N('leg','Distance between legs',10,60,1,30,'mm'),N('sag','Corrected sagitta',.01,2,.01,.5,'mm'),N('zero','Zero error',-.1,.1,.01,0,'mm')],'R = a²/(6h) + h/2',p=>[out('Indicated sagitta',p.sag+p.zero,'mm'),out('Radius of curvature',p.leg**2/(6*p.sag)+p.sag/2,'mm')],'Equilateral tripod; sagitta is corrected for zero error. Screw backlash and surface contact are not reproduced.');
add('microscope','Travelling microscope: bore diameter','instrument',[N('left','Left edge position',0,30,.01,12.3,'mm'),N('diameter','Bore diameter',.05,3,.01,.45,'mm')],'diameter = right-edge reading − left-edge reading',p=>[out('Left reading',p.left,'mm'),out('Right reading',p.left+p.diameter,'mm'),out('Bore diameter',p.diameter,'mm')],'Readout and difference model; focusing, crosshair alignment, and optical resolution are not simulated.');
add('forces','Parallelogram of forces','forces',[N('f1','Force 1',.5,8,.1,3,'N'),N('f2','Force 2',.5,8,.1,4,'N'),N('angle','Included angle',10,170,1,90,'°')],'R² = F₁² + F₂² + 2F₁F₂ cosθ',p=>{let r=Math.sqrt(p.f1**2+p.f2**2+2*p.f1*p.f2*Math.cos(rad(p.angle)));return [out('Resultant / equilibrant magnitude',r,'N'),out('Equivalent hanging mass',r/G,'kg')];},'Massless strings, frictionless pulleys, and concurrent forces. Equilibrant direction is opposite the resultant.');
add('moments','Principle of moments','forces',[N('known','Known mass',.05,1,.01,.2,'kg'),N('left','Known-mass distance',.05,.45,.01,.3,'m'),N('right','Unknown-mass distance',.05,.45,.01,.2,'m')],'m₁d₁ = m₂d₂',p=>[out('Balanced unknown mass',p.known*p.left/p.right,'kg'),out('Moment',p.known*G*p.left,'N·m')],'Uniform beam supported at its center of gravity; its own weight produces no moment. Off-center support requires the beam-weight term.');
for(const [id,title]of[['utube','Relative density: U-tube'],['hare','Relative density: Hare’s apparatus']])add(id,title,'fluid',[N('water','Water-column height',5,40,.5,20,'cm'),N('liquid','Test-liquid height',5,40,.5,25,'cm')],'ρliquid / ρwater = hwater / hliquid',p=>[out('Relative density',p.water/p.liquid),out('Liquid density',1000*p.water/p.liquid,'kg/m³')],id==='utube'?'Immiscible liquids, equal pressure at the same horizontal level. Heights are measured from the common interface.':'Both liquid columns share the same pressure reduction. Capillary and vapor-pressure differences are neglected.');
add('hydrometer','Weighted test-tube hydrometer','fluid',[N('mass','Total floating mass',10,100,1,40,'g'),N('area','Tube cross-sectional area',1,8,.1,4,'cm²'),N('depth','Immersed cylindrical length',3,20,.1,10,'cm')],'ρ = m / Vdisplaced',p=>[out('Displaced volume',p.area*p.depth,'cm³'),out('Liquid density',p.mass/(p.area*p.depth)*1000,'kg/m³')],'Cylindrical displacement approximation; the bottom correction volume is omitted.');
add('pendulum-g','Determine g with a simple pendulum','pendulum',[length,N('g','Model gravitational acceleration',1.62,15,.01,9.81,'m/s²'),N('cycles','Number of oscillations',5,40,1,20)],'T² = (4π²/g)L; g = 4π² / gradient',p=>{let T=2*Math.PI*Math.sqrt(p.length/p.g);return [out('Time for N oscillations',T*p.cycles,'s'),out('Period',T,'s'),out('Period squared',T*T,'s²'),out('Recovered g',4*Math.PI**2*p.length/(T*T),'m/s²')];},'Small amplitude, no damping, length measured from pivot to bob center. Stopwatch reaction time is not included.');
add('hooke','Hooke’s law and spring constant','spring',[mass,N('k','Model spring constant',5,100,1,20,'N/m')],'F = kx; k = gradient of F against x',p=>[out('Load',p.mass*G,'N'),out('Extension',p.mass*G/p.k,'m'),out('Recovered spring constant',p.k,'N/m')],'Linear elastic spring below its elastic limit; mass of spring neglected.');
for(const [id,title]of[['sonometer-tension','Sonometer: tension and frequency'],['sonometer-length','Sonometer: length and frequency']])add(id,title,'wave',[N('length','Vibrating length',.1,1,.01,.5,'m'),N('tension','String tension',2,100,1,40,'N'),N('mu','Linear density',.0002,.002,.0001,.001,'kg/m')],'f = (1/2L)√(T/μ)',p=>[out('Resonance frequency',Math.sqrt(p.tension/p.mu)/(2*p.length),'Hz'),out('Frequency squared',p.tension/p.mu/(4*p.length*p.length),'Hz²'),out('Inverse length',1/p.length,'m⁻¹')],'Fundamental transverse mode of an ideal string. Resonance detection by paper rider is represented by a numerical frequency, not an acoustic test.');
for(const [id,title]of[['resonance','Closed resonance tube: one fork'],['resonance-graph','Closed resonance tube: multiple forks']])add(id,title,'tube',[N('frequency','Fork frequency',200,800,10,400,'Hz'),N('speed','Model sound speed',320,360,1,343,'m/s'),N('correction','End correction',.002,.02,.001,.008,'m')],'L₁ + e = v/4f; L₂ − L₁ = v/2f',p=>[out('First resonance length',p.speed/(4*p.frequency)-p.correction,'m'),out('Second resonance length',3*p.speed/(4*p.frequency)-p.correction,'m'),out('Inverse frequency',1/p.frequency,'s'),out('Recovered speed',p.speed,'m/s')],'Closed–open tube, odd harmonics, constant end correction. Real resonance width and sound generation are not reproduced.');
add('glass-depth','Glass index by apparent depth','optics',[N('real','Real depth',2,30,.1,15,'mm'),N('index','Model refractive index',1.1,2,.01,1.5)],'n = real depth / apparent depth',p=>[out('Apparent depth',p.real/p.index,'mm'),out('Focus displacement',p.real-p.real/p.index,'mm'),out('Recovered index',p.index)],'Near-normal viewing; microscope-focus readings are ideal.');
add('critical-prism','Critical angle of glass','optics',[N('index','Model glass index',1.1,2,.01,1.5)],'n = 1/sin C',p=>[out('Critical angle',Math.asin(1/p.index)*180/Math.PI,'°'),out('Recovered index',p.index)],'Glass-to-air boundary. Prism alignment and beam divergence are omitted.');
add('prism-angle','Spectrometer: prism angle','optics',[N('face1','First reflected-ray bearing',10,30,.1,20,'°'),N('angle','Model prism angle',30,70,.1,60,'°')],'A = ½ separation of reflected-ray bearings',p=>[out('First bearing',p.face1,'°'),out('Second bearing',p.face1+2*p.angle,'°'),out('Recovered prism angle',p.angle,'°')],'Angle-reading model only; leveling, collimator focusing, telescope adjustments, and vernier averaging are not simulated.');
add('prism-deviation','Spectrometer: minimum deviation','optics',[N('angle','Prism angle',30,60,1,60,'°'),N('index','Model refractive index',1.2,1.8,.01,1.5)],'n = sin((A + Dmin)/2) / sin(A/2)',p=>[out('Minimum deviation',2*Math.asin(p.index*Math.sin(rad(p.angle)/2))*180/Math.PI-p.angle,'°'),out('Recovered index',p.index)],'Symmetric ray path through a prism in air. Wavelength dispersion and instrument adjustments are omitted.');
for(const [id,title]of[['convex','Convex lens: focal length'],['mirror','Concave mirror: focal length']])add(id,title,'optics',[N('f','Model focal length',5,20,.5,10,'cm'),N('multiple','Object distance / focal length',1.2,4,.1,2.5)],'1/f = 1/u + 1/v',p=>{let u=p.f*p.multiple,v=p.f*u/(u-p.f);return [out('Object distance',u,'cm'),out('Image distance',v,'cm'),out('Inverse object distance',1/u,'cm⁻¹'),out('Inverse image distance',1/v,'cm⁻¹'),out('Recovered focal length',u*v/(u+v),'cm')];},'Paraxial real-image model; no-parallax positioning and aberrations are not simulated.');
add('concave','Concave lens with a convex lens','optics',[N('focus','Magnitude of concave focal length',10,30,1,20,'cm'),N('object','Distance to converging virtual object',2,9,.5,5,'cm')],'1/f = 1/v − 1/uvirtual',p=>{let v=1/(1/p.object-1/p.focus);return [out('Virtual-object distance',p.object,'cm'),out('Final real-image distance',v,'cm'),out('Concave focal length',-p.focus,'cm')];},'A converging beam enters a diverging lens before its initial image plane; uvirtual < |f|. Upstream convex-lens construction is assumed.');
add('boyle','Quill tube: Boyle’s law','tube',[N('pressure','Atmospheric pressure',80,110,.5,101.3,'kPa'),N('head','Additional hydrostatic pressure',-20,40,1,10,'kPa'),N('v0','Reference gas volume',1,10,.1,5,'mL')],'P₁V₁ = P₂V₂',p=>[out('Gas pressure',p.pressure+p.head,'kPa'),out('Gas volume',p.pressure*p.v0/(p.pressure+p.head),'mL'),out('P × V',p.pressure*p.v0,'kPa·mL')],'Isothermal ideal gas. Hydrostatic head is entered as pressure; mercury handling and quill orientation are not reproduced.');
add('charles','Charles’s law','tube',[temp,N('v0','Volume at 0 °C',10,100,1,50,'mL')],'V/T = constant (T in kelvin)',p=>[out('Temperature',p.temp+273.15,'K'),out('Gas volume',p.v0*(p.temp+273.15)/273.15,'mL')],'Fixed gas amount at constant pressure.');
add('pressure-law','Constant-volume gas thermometer','tube',[temp,N('p0','Pressure at 0 °C',80,120,1,100,'kPa')],'P/T = constant (T in kelvin)',p=>[out('Temperature',p.temp+273.15,'K'),out('Gas pressure',p.p0*(p.temp+273.15)/273.15,'kPa')],'Ideal gas at fixed volume and amount.');
add('solid-heat','Specific heat: solid by mixtures','thermal',[N('solid','Hot-solid mass',.05,.3,.01,.1,'kg'),N('c','Model solid heat capacity',200,1000,10,390,'J/(kg·K)'),N('water','Water mass',.1,.5,.01,.2,'kg'),N('hot','Initial solid temperature',60,100,1,90,'°C')],'ms cs(Th − Tf) = mw cw(Tf − 20)',p=>{let tf=(p.solid*p.c*p.hot+p.water*4184*20)/(p.solid*p.c+p.water*4184);return [out('Final mixture temperature',tf,'°C'),out('Recovered specific heat',p.water*4184*(tf-20)/(p.solid*(p.hot-tf)),'J/(kg·K)')];},'Water starts at 20 °C. Calorimeter heat capacity and heat loss are neglected.');
add('liquid-mixtures','Specific heat: liquid by mixtures','thermal',[N('liquid','Test-liquid mass',.05,.3,.01,.1,'kg'),N('c','Model liquid heat capacity',1000,4500,100,2400,'J/(kg·K)'),N('water','Hot-water mass',.1,.5,.01,.2,'kg')],'heat lost by hot water = heat gained by liquid',p=>{let tf=(p.liquid*p.c*20+p.water*4184*80)/(p.liquid*p.c+p.water*4184);return [out('Final temperature',tf,'°C'),out('Recovered specific heat',p.water*4184*(80-tf)/(p.liquid*(tf-20)),'J/(kg·K)')];},'Ideal insulated mixture of hot water at 80 °C and test liquid at 20 °C; no heat of mixing.');
add('cooling','Specific heat: method of cooling','thermal',[N('c','Model liquid heat capacity',1000,4500,100,2400,'J/(kg·K)'),N('mass','Liquid mass',.05,.3,.01,.1,'kg'),N('time','Elapsed time',0,600,10,120,'s')],'T − Ta = (T₀ − Ta) exp[−Ht/(mc + Ccal)]',p=>{let rate=1.2/(p.mass*p.c+50);return [out('Temperature',25+45*Math.exp(-rate*p.time),'°C'),out('Cooling constant',rate,'s⁻¹'),out('Recovered specific heat',(1.2/rate-50)/p.mass,'J/(kg·K)')];},'Ambient 25 °C, initial 70 °C, heat-transfer coefficient 1.2 W/K and calorimeter capacity 50 J/K are assumed. Compare water and liquid under identical geometry.');
add('ice','Latent heat of fusion: ice','thermal',[N('ice','Ice mass',.005,.03,.001,.02,'kg'),N('water','Water mass',.2,.4,.01,.25,'kg'),N('initial','Initial water temperature',30,60,1,40,'°C')],'mw cw(Tw − Tf) = mi Lf + mi cw Tf',p=>[out('Final temperature',(p.water*4184*p.initial-p.ice*334000)/((p.water+p.ice)*4184),'°C'),out('Recovered latent heat',334000,'J/kg')],'Dry ice at 0 °C, complete melting, insulated calorimeter with negligible heat capacity.');
add('steam','Latent heat of vaporization: steam','thermal',[N('steam','Condensed steam mass',.001,.01,.001,.005,'kg'),N('water','Initial water mass',.2,.5,.01,.25,'kg')],'ms Lv + ms cw(100 − Tf) = mw cw(Tf − 20)',p=>[out('Final temperature',(p.steam*2257000+p.steam*4184*100+p.water*4184*20)/((p.water+p.steam)*4184),'°C'),out('Recovered latent heat',2257000,'J/kg')],'Dry saturated steam at 100 °C; all steam condenses. Heat losses and calorimeter capacity are neglected.');
add('dew','Relative humidity: dew point','thermal',[N('air','Air temperature',20,40,1,30,'°C'),N('depression','Air minus dew-point temperature',0,15,.5,8,'°C')],'RH = 100 psat(Tdew) / psat(Tair)',p=>[out('Dew point',p.air-p.depression,'°C'),out('Relative humidity',100*sat(p.air-p.depression)/sat(p.air),'%')],'Saturation pressure is approximated by the Tetens equation. Visual first-condensation detection is not simulated.');
add('wet-dry','Wet-and-dry-bulb hygrometer','thermal',[N('air','Dry-bulb temperature',20,40,1,30,'°C'),N('drop','Wet-bulb depression',0,10,.5,5,'°C')],'e ≈ es(Twet) − γP(Tdry − Twet)',p=>{let wet=p.air-p.drop,e=sat(wet)-.00066*(1+.00115*wet)*101.325*p.drop;return [out('Wet-bulb temperature',wet,'°C'),out('Relative humidity',Math.max(0,100*e/sat(p.air)),'%')];},'Ventilated psychrometer approximation at 101.325 kPa.');
add('thermal-conductivity','Searle’s thermal conductivity','thermal',[N('flow','Cooling-water mass flow',.001,.01,.001,.003,'kg/s'),N('rise','Water temperature rise',1,5,.1,2,'K'),N('gradient','Rod temperature difference',10,50,1,30,'K')],'k = (ṁ cw ΔTwater)L/(A ΔTrod)',p=>[out('Heat flow',p.flow*4184*p.rise,'W'),out('Thermal conductivity',p.flow*4184*p.rise*.1/(.0004*p.gradient),'W/(m·K)')],'Steady state, rod area 4 cm², thermometer spacing 10 cm; radial heat loss neglected.');
add('cell-internal','Cell e.m.f. and internal resistance','circuit',[N('emf','Model e.m.f.',1,3,.1,1.5,'V'),N('internal','Model internal resistance',.2,3,.1,1,'Ω'),N('load','External resistance',1,20,.5,5,'Ω')],'V = E − Ir',p=>{let i=p.emf/(p.internal+p.load);return [out('Current',i,'A'),out('Terminal voltage',i*p.load,'V'),out('Recovered internal resistance',p.internal,'Ω')];},'Ideal constant e.m.f. and internal resistance; polarization and cell depletion omitted.');
add('meter-bridge','Meter bridge: resistance comparison','circuit',[N('known','Known resistance',1,20,.5,5,'Ω'),N('unknown','Model unknown resistance',1,20,.5,8,'Ω'),N('contact','Jockey position',1,99,.1,50,'cm')],'X/R = l/(100 − l)',p=>{let bal=100*p.unknown/(p.unknown+p.known);return [out('Balance length',bal,'cm'),out('Null detector offset',p.contact-bal,'cm'),out('Resistance inferred at contact',p.known*p.contact/(100-p.contact),'Ω')];},'Uniform bridge wire, negligible end/contact resistances. Move the jockey until the detector offset is zero.');
add('temperature-resistance','Temperature coefficient of resistance','circuit',[N('temp','Wire temperature',0,100,1,40,'°C'),N('r0','Resistance at 0 °C',1,10,.1,5,'Ω'),N('alpha','Model temperature coefficient',.001,.006,.0001,.004,'K⁻¹')],'Rt = R₀(1 + αt)',p=>[out('Wire resistance',p.r0*(1+p.alpha*p.temp),'Ω'),out('Balance length against 5 Ω',100*(p.r0*(1+p.alpha*p.temp))/(5+p.r0*(1+p.alpha*p.temp)),'cm')],'Linear resistance-temperature relation; meter-bridge reference resistance is 5 Ω.');
for(const [id,title,mode]of[['pot-emf','Potentiometer: compare e.m.f.s','emf'],['pot-resistance','Potentiometer: compare resistances','res'],['pot-internal','Potentiometer: internal resistance','internal']])add(id,title,'circuit',[N('l1','First balance length',40,95,.5,80,'cm'),N('ratio','Second / first balance length',.2,.95,.01,.75),N('reference',mode==='emf'?'Reference e.m.f.':'Reference resistance',.5,10,.1,mode==='emf'?1.5:5,mode==='emf'?'V':'Ω')],mode==='internal'?'r = R(lopen/lload − 1)':'ratio of voltages = ratio of balance lengths',p=>[out('Second balance length',p.l1*p.ratio,'cm'),out(mode==='internal'?'Internal resistance':mode==='emf'?'Unknown e.m.f.':'Unknown resistance',mode==='internal'?p.reference*(1/p.ratio-1):p.reference*p.ratio,mode==='emf'?'V':'Ω')],'Uniform potential gradient and ideal null detection. This is a balance-reading model; wiring errors are not simulated.');
add('induction','Faraday and Lenz induction','circuit',[N('turns','Coil turns',10,500,10,100),N('field','Field change',-.5,.5,.01,.1,'T'),N('time','Time interval',.1,2,.1,.5,'s')],'ε = −N ΔΦ/Δt',p=>[out('Induced e.m.f.',-p.turns*.01*p.field/p.time,'V')],'Uniform field normal to a 0.01 m² coil; sign follows the chosen normal direction. Field topology and eddy currents are omitted.');
add('diode','Diode I–V characteristics','circuit',[N('bias','Diode bias',-5,.65,.01,.55,'V'),N('temp','Junction temperature',20,60,1,25,'°C')],'I = Is(exp(V/(nVT)) − 1)',p=>[out('Diode current',1e-9*(Math.exp(p.bias/(2*8.617333e-5*(p.temp+273.15)))-1)*1000,'mA')],'Illustrative Shockley model with Is=1 nA and n=2. No breakdown, self-heating, or series resistance; not a datasheet model.');
add('rectifier','CRO: rectification and smoothing','scope',[N('peak','Input peak voltage',1,12,.5,6,'V'),N('time','Time',0,.06,.0005,.012,'s'),S('mode','Rectifier',[[0,'Half-wave'],[1,'Full-wave'],[2,'Full-wave + capacitor']],1),N('capacitor','Filter capacitance',100,2200,100,1000,'µF')],'Vout = rectified Vin; ΔV ≈ I/(2fC)',p=>{let input=p.peak*Math.sin(2*Math.PI*50*p.time),rect=p.mode===0?Math.max(0,input):Math.abs(input),peak=Math.max(0,p.peak-.7),ripple=peak/(1000*100*p.capacitor*1e-6);return [out('Input voltage',input,'V'),out('Output voltage',p.mode===2?Math.max(0,peak-ripple*((p.time%.01)/.01)):Math.max(0,rect-.7),'V'),out('Approximate ripple',p.mode===2?ripple:0,'V')];},'50 Hz input; effective 0.7 V rectifier loss and 1 kΩ load. Capacitor ripple is a small-ripple sawtooth approximation, not a transient circuit solver.');
add('transistor','Common-emitter transistor','circuit',[N('base','Base current',0,80,1,20,'µA'),N('beta','Model current gain',50,200,5,100)],'IC ≈ βIB, limited by supply and load',p=>[out('Collector current',Math.min(4.8,p.base*p.beta/1000),'mA'),out('Collector voltage',5-Math.min(4.8,p.base*p.beta/1000),'V')],'5 V supply, 1 kΩ collector resistor, 0.2 V saturation. Idealized active/saturation transition; no frequency response.');
add('logic','Basic logic-gate truth tables','logic',[S('gate','Gate',[['AND','AND'],['OR','OR'],['NOT','NOT'],['NAND','NAND'],['NOR','NOR']]),S('a','Input A',[[0,'0'],[1,'1']],0),S('b','Input B',[[0,'0'],[1,'1']],0)],'Boolean input → output',p=>[out('Output',{AND:p.a&&p.b,OR:p.a||p.b,NOT:!p.a,NAND:!(p.a&&p.b),NOR:!(p.a||p.b)}[p.gate]?1:0)],'Ideal digital gates. Propagation delay, thresholds, and power wiring are not modeled. NOT ignores input B.');
add('young','Searle’s apparatus: Young’s modulus','spring',[N('mass','Added load',.1,5,.1,1,'kg'),N('length','Wire length',.5,3,.1,2,'m'),N('diameter','Wire diameter',.2,1,.01,.5,'mm'),N('modulus','Model Young’s modulus',50,220,5,200,'GPa')],'Y = FL/(A ΔL)',p=>{let a=Math.PI*(p.diameter*.001)**2/4,ext=p.mass*G*p.length/(a*p.modulus*1e9);return [out('Force',p.mass*G,'N'),out('Extension',ext*1000,'mm'),out('Stress',p.mass*G/a/1e6,'MPa')];},'Elastic wire, uniform circular section; reference-wire compensation and creep omitted.');
add('viscosity','Poiseuille capillary flow','fluid',[N('radius','Capillary radius',.1,.5,.01,.2,'mm'),N('head','Pressure head',2,20,.5,10,'cm'),N('viscosity','Model viscosity',.8,20,.1,1,'mPa·s')],'Q = πr⁴ΔP/(8ηL)',p=>[out('Pressure difference',1000*G*p.head/100,'Pa'),out('Volume flow rate',Math.PI*(p.radius*.001)**4*1000*G*p.head/100/(8*p.viscosity*.001*.2)*1e6,'mL/s')],'Laminar fully developed flow, tube length 0.2 m, fluid density 1000 kg/m³. Entrance losses and transition to turbulence omitted.');
add('surface-slide','Surface tension: slide or wire frame','fluid',[N('width','Wetted edge length',1,10,.1,5,'cm'),N('tension','Model surface tension',.025,.075,.001,.072,'N/m')],'F = 2γl (two wetted surfaces)',p=>[out('Detachment force above tare',2*p.tension*p.width/100,'N'),out('Equivalent added mass',2*p.tension*p.width/100/G*1000,'g')],'Zero contact angle and two wetted surfaces. Buoyancy correction and film drainage omitted.');
add('capillary-rise','Surface tension: capillary rise','fluid',[N('radius','Capillary radius',.1,1,.01,.3,'mm'),N('tension','Model surface tension',.025,.075,.001,.072,'N/m')],'h = 2γ cosθ/(ρgr)',p=>[out('Capillary rise',2*p.tension/(1000*G*p.radius*.001)*1000,'mm'),out('Inverse radius',1/p.radius,'mm⁻¹')],'Water density 1000 kg/m³, zero contact angle, meniscus-volume correction omitted.');
