export function defaults(id){return Object.fromEntries(models[id].controls.map(c=>[c.id,c.value]));}
export function calculate(id,values){const m=models[id];if(!m)throw Error('Unknown practical model');const p={...defaults(id),...values};for(const c of m.controls){if(c.options){if(!c.options.some(([v])=>v===p[c.id]))throw Error('Invalid option: '+c.id);}else if(!Number.isFinite(p[c.id])||p[c.id]<c.min-1e-9||p[c.id]>c.max+1e-9)throw Error('Out-of-range control: '+c.id);}return m.calculate(p);}
export function regression(points){if(points.length<3)return null;let n=points.length,sx=0,sy=0,sxx=0,sxy=0,syy=0;for(const [x,y]of points){sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;syy+=y*y;}let den=n*sxx-sx*sx;if(Math.abs(den)<1e-14)return null;let slope=(n*sxy-sx*sy)/den,intercept=(sy-slope*sx)/n,ss=syy-sy*sy/n,res=points.reduce((s,[x,y])=>s+(y-slope*x-intercept)**2,0);return {slope,intercept,r2:ss<1e-14?null:Math.max(0,1-res/ss)};}
