export function coverage(r){const valid=r.modules.filter(id=>models[id]);if(valid.length!==r.modules.length)return 'Missing model';if(r.gaps)return 'Partial';return valid.every(id=>models[id].kind==='demonstration')?'Guided demo':'Analytical model';}
