import {models,defaults,calculate,regression} from './models.js';
import {requirements,coverage,sourceLinks} from './catalog.js';
import {diagram} from './diagrams.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>typeof v==='number'?Number(v.toPrecision(6)).toString():String(v);
let req,model,params,result=[],db={};
try{db=JSON.parse(localStorage.getItem('chemia-practicals-v1')||'{}');if(!db||Array.isArray(db)||typeof db!=='object')db={};}catch{}
const session=()=>db[model.id]??=( {rows:[],conclusion:''});
function save(){try{localStorage.setItem('chemia-practicals-v1',JSON.stringify(db));$('#storage').textContent='Saved in this browser.';}catch{$('#storage').textContent='Browser storage is unavailable or full. Download your report to keep these records.';}}
$('#summary').textContent=`${requirements.length} checklist entries · ${Object.keys(models).length} activities`;
for(const t of new Set(requirements.map(r=>r.track)))$('#track').add(new Option(t,t));
function catalog(){let list=requirements.filter(r=>(!$('#track').value||r.track===$('#track').value)&&(!$('#filter').value||coverage(r)===$('#filter').value)&&`${r.title} ${r.unit} ${r.track}`.toLowerCase().includes($('#search').value.toLowerCase()));$('#count').textContent=`${list.length} matching practicals`;$('#catalog').innerHTML=list.map(r=>`<a href="#${r.id}" class="${req?.id===r.id?'active':''}"><small>${esc(r.track)} · ${esc(r.unit)}</small>${r.number}. ${esc(r.title)}<br><span class="badge">${coverage(r)}</span></a>`).join('')||'<p>No matching practicals.</p>';}
for(const id of ['track','search','filter'])$('#'+id).addEventListener('input',catalog);
function selectRequirement(){req=requirements.find(r=>r.id===decodeURIComponent(location.hash.slice(1)))||requirements[0];$('#heading').innerHTML=`<span class="badge">${coverage(req)}</span><h1>${esc(req.title)}</h1><p>${esc(req.track)} / ${esc(req.unit)}</p>${req.gaps?`<div class="gap"><b>Partial coverage:</b> ${esc(req.gaps)}</div>`:''}`;$('#module').innerHTML=req.modules.map(id=>`<option value="${id}">${esc(models[id].title)}</option>`).join('');selectModel();catalog();}
function selectModel(){model=models[$('#module').value];params=defaults(model.id);result=[];if(!Array.isArray(session().rows))session().rows=[];$('#fields').innerHTML=model.controls.map(c=>`<label>${esc(c.label)} ${c.unit?`(${esc(c.unit)})`:''}${c.options?`<select name="${c.id}">${c.options.map(([v,l])=>`<option value="${esc(v)}" ${v===params[c.id]?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input name="${c.id}" type="number" min="${c.min}" max="${c.max}" step="${c.step}" value="${params[c.id]}" required>`}</label>`).join('');$('#equation').textContent=model.equation||'Compare the selected conditions with the curated observations.';$('#limits').textContent=model.notes;$('#method').innerHTML=`<p><b>Apparatus represented:</b> ${esc((model.apparatus||[]).join(', '))}</p><ol>${(model.steps||['Choose a sample and test.','Run the demonstration.','Record the observation and interpretation.','Explain the limitations of this representation.']).map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`;$('#conclusion').value=session().conclusion||'';$('#notice').textContent='Adjust settings, then take a reading.';renderDiagram();renderNotebook();}
function renderDiagram(){ $('#diagram').innerHTML=diagram(model,params,result,result.length>0);$('#readings').innerHTML=result.filter(x=>!x.hidden).map(x=>`<div class="reading"><small>${esc(x.label)}</small><strong>${esc(fmt(x.value))}</strong> ${esc(x.unit)}</div>`).join('');}
$('#controls').addEventListener('input',()=>{if(!$('#controls').checkValidity())return;for(const c of model.controls)params[c.id]=c.options?$('#fields [name="'+c.id+'"]').value:Number($('#fields [name="'+c.id+'"]').value);result=[];renderDiagram();$('#notice').textContent='Settings changed. Take a new reading to record them.';});
$('#controls').addEventListener('submit',e=>{e.preventDefault();try{result=calculate(model.id,params);const values={};for(const c of model.controls)values[`${c.label}${c.unit?' ('+c.unit+')':''}`]=params[c.id];for(const r of result.filter(r=>!r.hidden))values[`${r.label}${r.unit?' ('+r.unit+')':''}`]=r.value;session().rows.push({at:new Date().toISOString(),values});save();renderDiagram();renderNotebook();$('#notice').textContent='Reading recorded.';}catch(e){$('#notice').textContent=e.message;}});
$('#reset').onclick=selectModel;$('#module').onchange=selectModel;window.addEventListener('hashchange',selectRequirement);
function renderNotebook(){const rows=session().rows,keys=[...new Set(rows.flatMap(r=>Object.keys(r.values)))];$('#table').innerHTML=rows.length?`<table><thead><tr><th>Run</th>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}<th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td>${keys.map(k=>`<td>${esc(fmt(r.values[k]??''))}</td>`).join('')}<td><button data-delete="${i}" aria-label="Delete reading ${i+1}">Delete</button></td></tr>`).join('')}</tbody></table>`:'<p>No readings yet. Run the activity to start your notebook.</p>';const numeric=keys.filter(k=>rows.every(r=>typeof r.values[k]==='number'));for(const id of ['x','y']){let previous=$('#'+id).value;$('#'+id).innerHTML=numeric.map(k=>`<option>${esc(k)}</option>`).join('');if(numeric.includes(previous))$('#'+id).value=previous;else $('#'+id).selectedIndex=id==='y'&&numeric.length>1?1:0;}renderGraph();}
$('#table').onclick=e=>{let b=e.target.closest('[data-delete]');if(b){session().rows.splice(Number(b.dataset.delete),1);save();renderNotebook();}};
function renderGraph(){const x=$('#x').value,y=$('#y').value,pts=session().rows.map(r=>[r.values[x],r.values[y]]).filter(p=>p.every(Number.isFinite));if(!x||!y||!pts.length){$('#graph').innerHTML='<p class="muted">Record numeric readings to plot a graph. Qualitative observations remain in the table.</p>';return;}let xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmax===xmin){xmin-=.5;xmax+=.5;}if(ymin===ymax){ymin-=.5;ymax+=.5;}let px=x=>70+(x-xmin)/(xmax-xmin)*660,py=y=>210-(y-ymin)/(ymax-ymin)*180;const fit=regression(pts);$('#graph').innerHTML=`<svg viewBox="0 0 820 270" role="img" aria-label="${esc(y)} against ${esc(x)}"><path d="M70 20V210H750" fill="none" stroke="#94aaa2"/>${fit?`<line x1="${px(Math.min(...xs))}" x2="${px(Math.max(...xs))}" y1="${py(fit.slope*Math.min(...xs)+fit.intercept)}" y2="${py(fit.slope*Math.max(...xs)+fit.intercept)}" stroke="#d2a44f"/>`:''}${pts.map(([a,b])=>`<circle cx="${px(a)}" cy="${py(b)}" r="5" fill="#168470"><title>${esc(fmt(a))}, ${esc(fmt(b))}</title></circle>`).join('')}<g font-size="11" fill="#45665e"><text x="70" y="230">${fmt(xmin)}</text><text x="700" y="230">${fmt(xmax)}</text><text x="3" y="30">${fmt(ymax)}</text><text x="3" y="210">${fmt(ymin)}</text><text x="300" y="258">${esc(x)}</text><text x="80" y="15">${esc(y)}</text></g></svg><p class="muted">${fit?`Least-squares fit: y = ${fmt(fit.slope)}x + ${fmt(fit.intercept)} · R² = ${fit.r2===null?'undefined (constant y)':fmt(fit.r2)}. Slope units: vertical-axis units / horizontal-axis units.`:'Record at least three readings with different horizontal values for a linear fit.'}</p>`;}
$('#x').onchange=renderGraph;$('#y').onchange=renderGraph;$('#conclusion').oninput=()=>{session().conclusion=$('#conclusion').value;save();};
function download(name,text,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const csv=rows=>rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');
$('#csv').onclick=()=>{const rows=session().rows,keys=[...new Set(rows.flatMap(r=>Object.keys(r.values)))];download(model.id+'.csv',csv([['Recorded at',...keys],...rows.map(r=>[r.at,...keys.map(k=>r.values[k])])]),'text/csv');};
$('#report').onclick=()=>download(model.id+'-report.md',`# ${req.title}\n\n${req.track}\n\nActivity: ${model.title}\n\nSupport: ${coverage(req)} / ${model.kind}\n\n${req.gaps||''}\n\n## Model boundaries\n${model.notes}\n\n## Relationship\n${model.equation||'Qualitative demonstration'}\n\n## Recorded observations\n${session().rows.map((r,i)=>`\n### Run ${i+1} — ${r.at}\n`+Object.entries(r.values).map(([k,v])=>`- ${k}: ${fmt(v)}`).join('\n')).join('\n')}\n\n## Student analysis\n${session().conclusion||'Not entered.'}\n`,'text/markdown');
$('#coverage').onclick=()=>download('curriculum-coverage.csv',csv([['Course','Number','Unit','Practical','Support','Activities','Missing or limited'],...requirements.map(r=>[r.track,r.number,r.unit,r.title,coverage(r),r.modules.map(id=>models[id].title).join('; '),r.gaps])]),'text/csv');
$('#sources').innerHTML='<p>Checklist organized from your supplied list. Support types describe this platform, not official accreditation. Consult your teacher and the official practical guides for assessment requirements.</p>'+sourceLinks.map(([title,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(title)}</a>`).join('');
selectRequirement();
